CREATE OR REPLACE FUNCTION public.phase2_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_any_role(auth.uid(),ARRAY['commandant','ict_admin']::public.app_role[]) $$;
CREATE OR REPLACE FUNCTION public.leave_stage_role(_stage integer) RETURNS public.app_role[] LANGUAGE sql IMMUTABLE AS $$ SELECT CASE _stage WHEN 1 THEN ARRAY['section_head']::public.app_role[] WHEN 2 THEN ARRAY['assistant_commissioner']::public.app_role[] WHEN 3 THEN ARRAY['dc_admin','dc_academy']::public.app_role[] WHEN 4 THEN ARRAY['commandant']::public.app_role[] WHEN 5 THEN ARRAY['hr_officer']::public.app_role[] ELSE ARRAY[]::public.app_role[] END $$;
ALTER TABLE public.leave_requests DROP CONSTRAINT leave_requests_leave_type_check;
ALTER TABLE public.leave_requests ADD CONSTRAINT leave_requests_leave_type_check CHECK (leave_type IN ('Annual','Sick','Emergency','Maternity','Special','Study'));
ALTER TABLE public.leave_requests ADD COLUMN leave_number text UNIQUE, ADD COLUMN delegate_officer_id uuid REFERENCES public.officers(id), ADD COLUMN attachments jsonb NOT NULL DEFAULT '[]', ADD COLUMN hr_processed_at timestamptz;
COMMENT ON COLUMN public.leave_requests.current_step IS 'DEPRECATED: display stage using leave_stage_role; terminal approvals now require HR processing.';
CREATE SEQUENCE public.leave_number_seq;
CREATE OR REPLACE FUNCTION public.prepare_leave() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.end_date<NEW.start_date THEN RAISE EXCEPTION 'End date cannot precede start date'; END IF; IF NEW.leave_number IS NULL THEN NEW.leave_number:='LNPATS/LV/'||extract(year from now())||'/'||lpad(nextval('public.leave_number_seq')::text,4,'0'); END IF; RETURN NEW; END $$;
CREATE TRIGGER prepare_leave BEFORE INSERT ON public.leave_requests FOR EACH ROW EXECUTE FUNCTION public.prepare_leave();
DROP POLICY "read leave" ON public.leave_requests;
CREATE POLICY "read leave" ON public.leave_requests FOR SELECT TO authenticated USING (requested_by=auth.uid() OR public.has_any_role(auth.uid(),ARRAY['section_head','assistant_commissioner','dc_admin','dc_academy','commandant','hr_officer']::public.app_role[]));
DROP POLICY "submit leave" ON public.leave_requests;
CREATE POLICY "submit leave" ON public.leave_requests FOR INSERT TO authenticated WITH CHECK (requested_by=auth.uid() AND stage=1 AND status='Pending' AND history='[]'::jsonb AND hr_processed_at IS NULL AND (EXISTS(SELECT 1 FROM public.officers o WHERE o.id=officer_id AND o.user_id=auth.uid()) OR public.has_any_role(auth.uid(),ARRAY['hr_officer','commandant']::public.app_role[])));
DROP POLICY leave_balances_admin_only ON public.leave_balances;
CREATE POLICY leave_balances_read ON public.leave_balances FOR SELECT TO authenticated USING (public.has_any_role(auth.uid(),ARRAY['hr_officer','commandant','section_head','assistant_commissioner','dc_admin','dc_academy']::public.app_role[]) OR EXISTS(SELECT 1 FROM public.officers o WHERE o.id=officer_id AND o.user_id=auth.uid()));
CREATE POLICY leave_balances_manage ON public.leave_balances FOR ALL TO authenticated USING (public.has_any_role(auth.uid(),ARRAY['hr_officer','commandant']::public.app_role[])) WITH CHECK (public.has_any_role(auth.uid(),ARRAY['hr_officer','commandant']::public.app_role[]));
CREATE OR REPLACE FUNCTION public.act_on_leave(_id uuid,_approve boolean,_note text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.leave_requests; n integer; b public.leave_balances; BEGIN SELECT * INTO r FROM public.leave_requests WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Request not found'; END IF; IF r.status<>'Pending' THEN RAISE EXCEPTION 'Request already closed'; END IF; IF NOT (public.has_any_role(auth.uid(),public.leave_stage_role(r.stage)) OR public.phase2_admin()) THEN RAISE EXCEPTION 'Not authorised for this stage'; END IF; IF NOT _approve AND nullif(trim(_note),'') IS NULL THEN RAISE EXCEPTION 'Rejection reason required'; END IF; IF _approve AND r.stage=5 THEN PERFORM pg_advisory_xact_lock(hashtext(r.officer_id::text||extract(year from r.start_date)::text)); SELECT * INTO b FROM public.leave_balances WHERE officer_id=r.officer_id AND year=extract(year from r.start_date) ORDER BY updated_at DESC LIMIT 1 FOR UPDATE; IF NOT FOUND THEN INSERT INTO public.leave_balances(officer_id,year) VALUES(r.officer_id,extract(year from r.start_date)) RETURNING * INTO b; END IF; n:=r.end_date-r.start_date+1; IF r.leave_type='Annual' AND n>coalesce(b.annual_leave_balance,30) THEN RAISE EXCEPTION 'Insufficient annual leave balance'; END IF; UPDATE public.leave_balances SET annual_leave_used=coalesce(annual_leave_used,0)+CASE WHEN r.leave_type='Annual' THEN n ELSE 0 END,annual_leave_balance=coalesce(annual_leave_balance,30)-CASE WHEN r.leave_type='Annual' THEN n ELSE 0 END,sick_leave_used=coalesce(sick_leave_used,0)+CASE WHEN r.leave_type='Sick' THEN n ELSE 0 END,emergency_leave_used=coalesce(emergency_leave_used,0)+CASE WHEN r.leave_type='Emergency' THEN n ELSE 0 END,updated_at=now() WHERE id=b.id; END IF; UPDATE public.leave_requests SET stage=CASE WHEN _approve THEN r.stage+1 ELSE r.stage END,status=CASE WHEN NOT _approve THEN 'Rejected' WHEN r.stage=5 THEN 'Approved' ELSE 'Pending' END,hr_processed_at=CASE WHEN _approve AND r.stage=5 THEN now() ELSE NULL END,history=r.history||jsonb_build_object('stage',r.stage,'action',CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,'by',(SELECT email FROM public.profiles WHERE id=auth.uid()),'note',_note,'at',now()) WHERE id=_id; INSERT INTO public.notifications(user_id,title,body) VALUES(r.requested_by,'Leave request update',CASE WHEN NOT _approve THEN 'Your leave request was rejected.' WHEN r.stage=5 THEN 'Your leave was approved and processed by HR.' ELSE 'Your leave request advanced to the next stage.' END); IF _approve AND r.stage<5 THEN INSERT INTO public.notifications(role,title,body) SELECT unnest(public.leave_stage_role(r.stage+1)),'Leave approval pending','A leave request awaits your review.'; END IF; END $$;
CREATE TABLE public.correspondence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), direction text NOT NULL CHECK(direction IN ('IN','OUT')),reference_number text UNIQUE NOT NULL,subject text NOT NULL,party text NOT NULL,record_date date NOT NULL DEFAULT current_date,keywords text,created_by uuid NOT NULL,stage integer NOT NULL DEFAULT 0 CHECK(stage BETWEEN 0 AND 7),status text NOT NULL DEFAULT 'Registered' CHECK(status IN ('Registered','In Progress','Completed','Archived')),office_id uuid REFERENCES public.offices(id),officer_id uuid REFERENCES public.officers(id),action_taken text,attachments jsonb NOT NULL DEFAULT '[]',history jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.correspondence TO authenticated; GRANT ALL ON public.correspondence TO service_role;
ALTER TABLE public.correspondence ENABLE ROW LEVEL SECURITY;
CREATE POLICY correspondence_read ON public.correspondence FOR SELECT TO authenticated USING(public.phase2_admin() OR public.has_any_role(auth.uid(),ARRAY['registry_officer','deputy_commandant']::public.app_role[]) OR created_by=auth.uid() OR EXISTS(SELECT 1 FROM public.officers o WHERE o.id=officer_id AND o.user_id=auth.uid()));
CREATE TRIGGER audit_correspondence AFTER INSERT OR UPDATE OR DELETE ON public.correspondence FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();
CREATE TABLE public.erp_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_number text UNIQUE NOT NULL,title text NOT NULL,category text NOT NULL,keywords text,author_id uuid NOT NULL,section_id uuid REFERENCES public.sections(id),status text NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','Pending','Published','Rejected','Archived')),stage integer NOT NULL DEFAULT 0 CHECK(stage BETWEEN 0 AND 5),current_version integer NOT NULL DEFAULT 1,history jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz);
GRANT SELECT ON public.erp_documents TO authenticated; GRANT ALL ON public.erp_documents TO service_role;
ALTER TABLE public.erp_documents ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.can_read_document(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.erp_documents d WHERE d.id=_id AND (d.author_id=auth.uid() OR public.phase2_admin() OR (d.category='Personnel Documents' AND public.has_any_role(auth.uid(),ARRAY['hr_officer']::public.app_role[])) OR (d.category='Financial Documents' AND public.has_any_role(auth.uid(),ARRAY['finance_officer']::public.app_role[])) OR (d.category NOT IN ('Personnel Documents','Financial Documents','Cadet Files') AND (d.status='Published' OR public.has_any_role(auth.uid(),ARRAY['section_head','assistant_commissioner','dc_admin','dc_academy']::public.app_role[]))) OR (d.category IN ('Personnel Documents','Financial Documents','Cadet Files') AND public.has_any_role(auth.uid(),ARRAY['section_head','assistant_commissioner','dc_admin','dc_academy']::public.app_role[]) AND EXISTS(SELECT 1 FROM public.officers o WHERE o.user_id=auth.uid() AND o.section_id=d.section_id)))) $$;
CREATE POLICY documents_read ON public.erp_documents FOR SELECT TO authenticated USING(public.can_read_document(id));
CREATE TRIGGER audit_erp_documents AFTER INSERT OR UPDATE OR DELETE ON public.erp_documents FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();
CREATE TABLE public.document_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES public.erp_documents(id),version integer NOT NULL,file_path text NOT NULL,file_name text NOT NULL,change_log text NOT NULL,signature text,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(document_id,version));
GRANT SELECT ON public.document_versions TO authenticated; GRANT ALL ON public.document_versions TO service_role;
ALTER TABLE public.document_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY versions_read ON public.document_versions FOR SELECT TO authenticated USING(public.can_read_document(document_id));
CREATE TRIGGER audit_document_versions AFTER INSERT OR UPDATE OR DELETE ON public.document_versions FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();
CREATE TABLE public.registry_counters(direction text NOT NULL,year integer NOT NULL,last_number integer NOT NULL DEFAULT 0,PRIMARY KEY(direction,year));
GRANT ALL ON public.registry_counters TO service_role;
ALTER TABLE public.registry_counters ENABLE ROW LEVEL SECURITY;
CREATE TRIGGER audit_registry_counters AFTER INSERT OR UPDATE OR DELETE ON public.registry_counters FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();
CREATE OR REPLACE FUNCTION public.next_registry_reference(_direction text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer;y integer:=extract(year from now()); BEGIN IF _direction NOT IN ('IN','OUT') OR NOT (public.phase2_admin() OR public.has_any_role(auth.uid(),ARRAY['registry_officer']::public.app_role[])) THEN RAISE EXCEPTION 'Not authorised'; END IF; INSERT INTO public.registry_counters(direction,year,last_number) VALUES(_direction,y,1) ON CONFLICT(direction,year) DO UPDATE SET last_number=registry_counters.last_number+1 RETURNING last_number INTO n; RETURN 'LNPATS/'||_direction||'/'||y||'/'||lpad(n::text,4,'0'); END $$;
CREATE SEQUENCE public.document_number_seq;
CREATE OR REPLACE FUNCTION public.phase2_workflow(_module text,_id uuid,_action text,_payload jsonb DEFAULT '{}') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.correspondence;d public.erp_documents;v public.document_versions;rid uuid;roles public.app_role[];h jsonb;next_status text;path text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; h:=jsonb_build_object('action',_action,'by',(SELECT email FROM public.profiles WHERE id=auth.uid()),'at',now(),'note',_payload->>'note'); IF _module='registry' THEN IF _action='create' THEN IF NOT (public.phase2_admin() OR public.has_any_role(auth.uid(),ARRAY['registry_officer']::public.app_role[])) THEN RAISE EXCEPTION 'Registry permission required'; END IF; INSERT INTO public.correspondence(direction,reference_number,subject,party,record_date,keywords,created_by,attachments,history) VALUES(_payload->>'direction',public.next_registry_reference(_payload->>'direction'),_payload->>'subject',_payload->>'party',coalesce((_payload->>'record_date')::date,current_date),_payload->>'keywords',auth.uid(),coalesce(_payload->'attachments','[]'),jsonb_build_array(h)) RETURNING id INTO rid; INSERT INTO public.notifications(role,title,body) VALUES('registry_officer','Correspondence registered','A correspondence record is ready for review.'); RETURN rid; END IF; SELECT * INTO c FROM public.correspondence WHERE id=_id FOR UPDATE; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.correspondence WHERE id=_id AND (public.phase2_admin() OR public.has_any_role(auth.uid(),ARRAY['registry_officer','deputy_commandant']::public.app_role[]) OR EXISTS(SELECT 1 FROM public.officers WHERE id=c.officer_id AND user_id=auth.uid()))) THEN RAISE EXCEPTION 'Not authorised'; END IF; roles:=CASE c.stage WHEN 1 THEN ARRAY['deputy_commandant']::public.app_role[] WHEN 2 THEN ARRAY['commandant']::public.app_role[] ELSE ARRAY['registry_officer']::public.app_role[] END; IF NOT (public.phase2_admin() OR public.has_any_role(auth.uid(),roles) OR (c.stage=5 AND EXISTS(SELECT 1 FROM public.officers WHERE id=c.officer_id AND user_id=auth.uid()))) THEN RAISE EXCEPTION 'Not authorised for this stage'; END IF; IF _action='advance' THEN IF c.stage>=7 THEN RAISE EXCEPTION 'Record archived'; END IF; IF c.stage=3 AND nullif(_payload->>'office_id','') IS NULL THEN RAISE EXCEPTION 'Choose an office'; END IF; IF c.stage=4 AND nullif(_payload->>'officer_id','') IS NULL THEN RAISE EXCEPTION 'Choose an officer'; END IF; IF c.stage=5 AND nullif(trim(_payload->>'note'),'') IS NULL THEN RAISE EXCEPTION 'Action taken is required'; END IF; UPDATE public.correspondence SET stage=c.stage+1,status=CASE WHEN c.stage=6 THEN 'Archived' WHEN c.stage=5 THEN 'Completed' ELSE 'In Progress' END,office_id=CASE WHEN c.stage=3 THEN (_payload->>'office_id')::uuid ELSE office_id END,officer_id=CASE WHEN c.stage=4 THEN (_payload->>'officer_id')::uuid ELSE officer_id END,action_taken=CASE WHEN c.stage=5 THEN _payload->>'note' ELSE action_taken END,history=history||h WHERE id=_id; IF c.stage=4 THEN INSERT INTO public.notifications(user_id,title,body) SELECT user_id,'New correspondence assigned',c.reference_number FROM public.officers WHERE id=(_payload->>'officer_id')::uuid AND user_id IS NOT NULL; ELSE INSERT INTO public.notifications(role,title,body) VALUES(CASE WHEN c.stage=0 THEN 'deputy_commandant'::public.app_role WHEN c.stage=1 THEN 'commandant'::public.app_role ELSE 'registry_officer'::public.app_role END,'Registry action required',c.reference_number); END IF; ELSIF _action='edit' AND c.stage=0 THEN UPDATE public.correspondence SET subject=coalesce(_payload->>'subject',subject),party=coalesce(_payload->>'party',party),keywords=coalesce(_payload->>'keywords',keywords),history=history||h WHERE id=_id; ELSIF _action='delete' AND c.stage=0 THEN DELETE FROM public.correspondence WHERE id=_id; ELSE RAISE EXCEPTION 'Action not available'; END IF; RETURN _id; ELSIF _module='documents' THEN IF _action='create' THEN path:=_payload->>'file_path'; IF path NOT LIKE auth.uid()::text||'/%' THEN RAISE EXCEPTION 'Invalid file ownership'; END IF; INSERT INTO public.erp_documents(document_number,title,category,keywords,author_id,section_id,history) VALUES('LNPATS/DOC/'||extract(year from now())||'/'||lpad(nextval('public.document_number_seq')::text,4,'0'),_payload->>'title',_payload->>'category',_payload->>'keywords',auth.uid(),nullif(_payload->>'section_id','')::uuid,jsonb_build_array(h)) RETURNING id INTO rid; INSERT INTO public.document_versions(document_id,version,file_path,file_name,change_log,signature,created_by) VALUES(rid,1,path,_payload->>'file_name',coalesce(_payload->>'change_log','Initial version'),_payload->>'signature',auth.uid()); RETURN rid; END IF; SELECT * INTO d FROM public.erp_documents WHERE id=_id FOR UPDATE; IF NOT FOUND OR NOT public.can_read_document(_id) THEN RAISE EXCEPTION 'Document unavailable'; END IF; IF _action IN ('submit','edit','version','rollback','delete','archive') AND NOT (d.author_id=auth.uid() OR public.phase2_admin()) THEN RAISE EXCEPTION 'Author permission required'; END IF; IF _action='submit' THEN IF d.status NOT IN ('Draft','Rejected') THEN RAISE EXCEPTION 'Cannot submit this document'; END IF; UPDATE public.erp_documents SET status='Pending',stage=1,history=history||h WHERE id=_id; INSERT INTO public.notifications(role,title,body) VALUES('section_head','Document awaiting approval',d.document_number); ELSIF _action IN ('approve','reject') THEN roles:=CASE d.stage WHEN 1 THEN ARRAY['section_head']::public.app_role[] WHEN 2 THEN ARRAY['assistant_commissioner']::public.app_role[] WHEN 3 THEN ARRAY['dc_admin','dc_academy']::public.app_role[] WHEN 4 THEN ARRAY['commandant']::public.app_role[] ELSE ARRAY[]::public.app_role[] END; IF d.status<>'Pending' OR NOT (public.phase2_admin() OR public.has_any_role(auth.uid(),roles)) THEN RAISE EXCEPTION 'Not authorised for this stage'; END IF; IF _action='reject' AND nullif(trim(_payload->>'note'),'') IS NULL THEN RAISE EXCEPTION 'Rejection reason required'; END IF; next_status:=CASE WHEN _action='reject' THEN 'Rejected' WHEN d.stage=4 THEN 'Published' ELSE 'Pending' END; UPDATE public.erp_documents SET status=next_status,stage=CASE WHEN _action='approve' THEN d.stage+1 ELSE stage END,published_at=CASE WHEN next_status='Published' THEN now() ELSE NULL END,history=history||h WHERE id=_id; INSERT INTO public.notifications(user_id,title,body) VALUES(d.author_id,'Document '||lower(next_status),d.document_number); IF next_status='Pending' THEN INSERT INTO public.notifications(role,title,body) SELECT unnest(CASE d.stage WHEN 1 THEN ARRAY['assistant_commissioner']::public.app_role[] WHEN 2 THEN ARRAY['dc_admin','dc_academy']::public.app_role[] ELSE ARRAY['commandant']::public.app_role[] END),'Document awaiting approval',d.document_number; END IF; ELSIF _action IN ('version','rollback') THEN IF d.status='Pending' THEN RAISE EXCEPTION 'Cannot change a version during review'; END IF; IF _action='rollback' THEN SELECT * INTO v FROM public.document_versions WHERE document_id=_id AND version=(_payload->>'version')::integer; IF NOT FOUND THEN RAISE EXCEPTION 'Version not found'; END IF; ELSE path:=_payload->>'file_path'; IF path NOT LIKE auth.uid()::text||'/%' THEN RAISE EXCEPTION 'Invalid file ownership'; END IF; END IF; INSERT INTO public.document_versions(document_id,version,file_path,file_name,change_log,signature,created_by) VALUES(_id,d.current_version+1,CASE WHEN _action='rollback' THEN v.file_path ELSE path END,CASE WHEN _action='rollback' THEN v.file_name ELSE _payload->>'file_name' END,coalesce(_payload->>'change_log','Restored version '||v.version),_payload->>'signature',auth.uid()); UPDATE public.erp_documents SET current_version=current_version+1,status='Draft',stage=0,published_at=NULL,history=history||h WHERE id=_id; ELSIF _action='edit' AND d.status IN ('Draft','Rejected') THEN UPDATE public.erp_documents SET title=coalesce(_payload->>'title',title),keywords=coalesce(_payload->>'keywords',keywords),history=history||h WHERE id=_id; ELSIF _action='archive' AND d.status<>'Pending' THEN UPDATE public.erp_documents SET status='Archived',history=history||h WHERE id=_id; ELSIF _action='delete' AND d.status IN ('Draft','Rejected') THEN DELETE FROM public.document_versions WHERE document_id=_id; DELETE FROM public.erp_documents WHERE id=_id; ELSE RAISE EXCEPTION 'Action not available'; END IF; RETURN _id; END IF; RAISE EXCEPTION 'Unknown module'; END $$;
CREATE OR REPLACE FUNCTION public.leave_submission_notify() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.notifications(role,title,body) VALUES('section_head','Leave request submitted',NEW.leave_number); RETURN NEW; END $$;
CREATE TRIGGER notify_leave_submission AFTER INSERT ON public.leave_requests FOR EACH ROW EXECUTE FUNCTION public.leave_submission_notify();
CREATE OR REPLACE FUNCTION public.record_activity(_module text,_id uuid,_action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE allowed boolean:=false; BEGIN IF _action NOT IN ('VIEW','DOWNLOAD') THEN RAISE EXCEPTION 'Invalid activity'; END IF; IF _module='documents' THEN allowed:=public.can_read_document(_id); ELSIF _module='registry' THEN SELECT EXISTS(SELECT 1 FROM public.correspondence c WHERE c.id=_id AND (public.phase2_admin() OR public.has_any_role(auth.uid(),ARRAY['registry_officer','deputy_commandant']::public.app_role[]) OR c.created_by=auth.uid() OR EXISTS(SELECT 1 FROM public.officers WHERE id=c.officer_id AND user_id=auth.uid()))) INTO allowed; ELSIF _module='leave' THEN SELECT EXISTS(SELECT 1 FROM public.leave_requests WHERE id=_id AND (requested_by=auth.uid() OR public.has_any_role(auth.uid(),ARRAY['section_head','assistant_commissioner','dc_admin','dc_academy','hr_officer','commandant']::public.app_role[]))) INTO allowed; END IF; IF NOT allowed THEN RAISE EXCEPTION 'Not authorised'; END IF; INSERT INTO public.audit_logs(user_id,user_email,action,table_name,record_id,ip_address) VALUES(auth.uid(),(SELECT email FROM public.profiles WHERE id=auth.uid()),_action,_module,_id::text,nullif(current_setting('request.headers',true),'')::jsonb->>'x-forwarded-for'); END $$;
CREATE POLICY phase2_storage_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='phase2-files' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY phase2_storage_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='phase2-files' AND ((storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.document_versions v WHERE v.file_path=name AND public.can_read_document(v.document_id)) OR EXISTS(SELECT 1 FROM public.correspondence c WHERE c.attachments::text LIKE '%'||name||'%') OR EXISTS(SELECT 1 FROM public.leave_requests l WHERE l.attachments::text LIKE '%'||name||'%')));
REVOKE ALL ON FUNCTION public.phase2_workflow(text,uuid,text,jsonb), public.record_activity(text,uuid,text),public.next_registry_reference(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.phase2_workflow(text,uuid,text,jsonb),public.record_activity(text,uuid,text),public.next_registry_reference(text) TO authenticated;
CREATE POLICY phase2_audit_read ON public.audit_logs FOR SELECT TO authenticated USING(public.phase2_admin() OR public.has_any_role(auth.uid(),ARRAY['dc_academy']::public.app_role[]));
INSERT INTO public.correspondence(direction,reference_number,subject,party,record_date,created_by,officer_id) SELECT 'IN',coalesce(reference_number,'LEGACY-IN-'||id::text),coalesce(subject,'Legacy correspondence'),coalesce(sender,''),coalesce(received_date,current_date),coalesce((SELECT id FROM public.profiles ORDER BY created_at LIMIT 1),'00000000-0000-0000-0000-000000000000'::uuid),assigned_to FROM public.incoming_mail;
INSERT INTO public.correspondence(direction,reference_number,subject,party,record_date,created_by) SELECT 'OUT',coalesce(reference_number,'LEGACY-OUT-'||id::text),coalesce(subject,'Legacy correspondence'),coalesce(recipient,''),coalesce(dispatch_date,current_date),coalesce((SELECT id FROM public.profiles ORDER BY created_at LIMIT 1),'00000000-0000-0000-0000-000000000000'::uuid) FROM public.outgoing_mail;
COMMENT ON TABLE public.incoming_mail IS 'DEPRECATED: Phase 2 correspondence stores incoming and outgoing mail; existing rows backfilled.'; COMMENT ON TABLE public.outgoing_mail IS 'DEPRECATED: replaced by correspondence; existing rows backfilled.';